            A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
        return C;
    }
    auto P = torch::empty({splits, M, N}, A.options());
    matmul_splitk_partial_kernel<<<grid, block, SMEM_BYTES, stream>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), P.data_ptr<float>(), M, N, K);
    int rthreads = 256;
    int rblocks = (total + rthreads - 1) / rthreads;
